<?php
declare(strict_types=1);
namespace CommunityHub;
final class ContentAdmin {
 const FLAGS=['applications','hud','hud_logo','hud_name','hud_postals'];
 const LIMITS=['description'=>500,'public_url'=>500,'hero_title'=>160,'hero_image'=>500,'hero_body'=>2000,'side_title'=>160,'highlights'=>600,'section_title'=>160,'section_body'=>5000,'cta_title'=>160,'cta_body'=>2000,'cta_label'=>80,'cta_url'=>500,'about_title'=>160,'about_body'=>12000,'gallery_title'=>160,'gallery_body'=>2000];
 public static function image(string $key,int $max):array{$f=$_FILES[$key]??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))throw new HttpError('Choose a PNG, JPEG or WebP image.');if($f['size']>$max)throw new HttpError('Image exceeds the upload limit.',413);$bytes=file_get_contents($f['tmp_name']);$info=@getimagesizefromstring($bytes);$mime=$info['mime']??'';if(!in_array($mime,['image/png','image/jpeg','image/webp'],true))throw new HttpError('Choose a PNG, JPEG or WebP image.');return [$bytes,$mime,hash('sha256',$bytes)];}
 public static function websiteInput(array $d):array{$out=[];foreach(self::LIMITS as $key=>$max)$out[$key]=App::text($d[$key]??'',$key,$max,true);foreach(['hero_title','side_title','cta_title','cta_label','about_title','gallery_title'] as $key)if($out[$key]==='')throw new HttpError('Titles and button labels cannot be empty.');if($out['public_url']){$url=parse_url($out['public_url']);if(!$url||!filter_var($out['public_url'],FILTER_VALIDATE_URL)||!in_array($url['scheme']??'',['http','https'],true)||isset($url['user'])||isset($url['pass']))throw new HttpError('Enter a valid HTTP or HTTPS public website address.');$out['public_url']=$url['scheme'].'://'.$url['host'].(isset($url['port'])?':'.$url['port']:'');}$cta=$out['cta_url'];$url=parse_url($cta);if(!(preg_match('~^/(?!/)~',$cta)&&!preg_match('/[\\\s]/',$cta))&&(!filter_var($cta,FILTER_VALIDATE_URL)||($url['scheme']??'')!=='https'||isset($url['user'])||isset($url['pass'])))throw new HttpError('Use a website path beginning with / or an HTTPS button link.');if($out['hero_image']&&!preg_match('~^/(images/community-city-v3\.png|gallery/image/\d+)$~',$out['hero_image']))throw new HttpError('Choose a city backdrop, a gallery image or no backdrop.');if(count(array_filter(preg_split('/\R/',$out['highlights'])))>3)throw new HttpError('Use at most three highlight lines.');foreach(['show_stats','show_resources','show_section','show_cta'] as $key)$out[$key]=!empty($d[$key]);return $out;}
 private static function galleryInput(array $d):array{$order=filter_var($d['sort_order']??0,FILTER_VALIDATE_INT);if($order===false||abs($order)>100000)throw new HttpError('Use a whole-number display order between -100000 and 100000.');return [App::text($d['title']??null,'Title',160),App::text($d['caption']??'','Caption',2000,true),$order,(int)!empty($d['is_published'])];}
 public static function handle(array $u,string $method,string $path,array $d):void{
  if(str_starts_with($path,'/community/manage')){Domain::role($u,Domain::CONTENT_STAFF);self::content($u,$method,$path,$d);return;}
  Domain::role($u,Domain::ADMINS);
  if($method==='POST'){
   if($path==='/admin/appearance/features'){App::transaction(function()use($d){foreach(self::FLAGS as $flag)App::query('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',['tablet_'.$flag.'_enabled',!empty($d[$flag])?'1':'0']);});App::redirect('/admin/appearance');}
   if($path==='/admin/appearance/logo'){[$bytes,$mime,$hash]=self::image('logo',262144);App::query('INSERT INTO community_branding(id,file_data,mime_type,sha256) VALUES(1,?,?,?) ON DUPLICATE KEY UPDATE file_data=VALUES(file_data),mime_type=VALUES(mime_type),sha256=VALUES(sha256)',[$bytes,$mime,$hash]);App::redirect('/admin/appearance');}
   if($path==='/admin/appearance/logo/remove'){App::query('UPDATE community_branding SET file_data=NULL,mime_type=NULL,sha256=NULL WHERE id=1');App::redirect('/admin/appearance');}
   if($path==='/admin/website'){$content=self::websiteInput($d);App::query("INSERT INTO site_settings(setting_key,setting_value) VALUES('public_website_content',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)",[json_encode($content,JSON_THROW_ON_ERROR)]);App::redirect('/admin/website');}
   if($path==='/admin/website/gallery'){[$bytes,$mime,$hash]=self::image('image',4194304);$values=self::galleryInput($d);App::query('INSERT INTO community_gallery(title,caption,sort_order,is_published,file_data,mime_type,sha256,created_by) VALUES(?,?,?,?,?,?,?,?)',[...$values,$bytes,$mime,$hash,$u['id']]);App::redirect('/admin/website');}
   if(preg_match('~^/admin/website/gallery/(\d+)/(save|remove|restore)$~',$path,$m)){$id=(int)$m[1];if(!App::row('SELECT id FROM community_gallery WHERE id=?',[$id]))throw new HttpError('Image not found.',404);if($m[2]==='save')App::query('UPDATE community_gallery SET title=?,caption=?,sort_order=?,is_published=? WHERE id=?',[...self::galleryInput($d),$id]);else App::query('UPDATE community_gallery SET is_removed=? WHERE id=?',[(int)($m[2]==='remove'),$id]);App::redirect('/admin/website');}
   throw new HttpError('Appearance action not found.',404);
  }
  if(preg_match('~^/admin/website/gallery/(\d+)/image$~',$path,$m)){$r=App::row('SELECT file_data,mime_type FROM community_gallery WHERE id=?',[(int)$m[1]]);if(!$r)throw new HttpError('Image not found.',404);header('Content-Type: '.$r['mime_type']);header('Cache-Control: private, no-store');echo $r['file_data'];return;}
  if($path==='/admin/appearance'){$brand=Domain::branding();View::layout('Appearance & in-game',function()use($brand){View::heading('Appearance & in-game','One community identity across the website, tablet and duty HUD.');?><section class="grid two"><article class="panel"><h2>Community logo</h2><?php if($brand['logo']):?><img class="logo-preview" src="<?=escape($brand['logo'])?>" alt="Community logo"><?php endif?><form method="post" action="/admin/appearance/logo" enctype="multipart/form-data"><?php View::csrf();?><label>PNG, JPEG or WebP · up to 256 KB<input type="file" name="logo" accept="image/png,image/jpeg,image/webp" required></label><button class="btn">Save logo</button></form><?php View::form('/admin/appearance/logo/remove',[],'Use initials instead');?></article><article class="panel"><h2>In-game features & HUD display</h2><?php $labels=['applications'=>'In-game applications','hud'=>'Duty HUD','hud_logo'=>'HUD community logo','hud_name'=>'HUD community name','hud_postals'=>'HUD nearest postal'];$fields=[];foreach($labels as $k=>$label)$fields[$k]=['label'=>$label,'type'=>'checkbox'];View::form('/admin/appearance/features',$fields,'Save display settings',$brand['features']);?></article></section><?php });return;}
  if($path==='/admin/website'){View::layout('Website content',function(){View::heading('Website content','Customize the public pages and gallery.');$content=Web::publicContent();$fields=[];foreach(self::LIMITS as $key=>$max)$fields[$key]=['label'=>ucfirst(str_replace('_',' ',$key)),'max'=>$max,'type'=>in_array($key,['hero_body','section_body','about_body','highlights'],true)?'textarea':'text'];foreach(['show_stats','show_resources','show_section','show_cta'] as $key)$fields[$key]=['label'=>ucfirst(str_replace('_',' ',$key)),'type'=>'checkbox'];View::form('/admin/website',$fields,'Save website content',$content);?><section class="panel"><h2>Add gallery image</h2><form method="post" action="/admin/website/gallery" enctype="multipart/form-data"><?php View::csrf();?><label>Title<input name="title" maxlength="160" required></label><label>Caption<textarea name="caption" maxlength="2000"></textarea></label><label>Display order<input type="number" name="sort_order" value="0"></label><label>Published<input type="checkbox" name="is_published" value="1" checked></label><label>Image · up to 4 MB<input type="file" name="image" accept="image/png,image/jpeg,image/webp" required></label><button class="btn">Add image</button></form></section><?php foreach(App::rows('SELECT id,title,caption,sort_order,is_published,is_removed FROM community_gallery ORDER BY is_removed,sort_order,id DESC') as $r){?><section class="panel"><img class="gallery-editor-preview" src="/admin/website/gallery/<?=(int)$r['id']?>/image" alt="<?=escape($r['title'])?>"><?php View::form('/admin/website/gallery/'.$r['id'].'/save',['title'=>['label'=>'Title','required'=>true,'max'=>160],'caption'=>['label'=>'Caption','type'=>'textarea','max'=>2000],'sort_order'=>['label'=>'Order','type'=>'number'],'is_published'=>['label'=>'Published','type'=>'checkbox']],'Save image',$r);View::form('/admin/website/gallery/'.$r['id'].'/'.($r['is_removed']?'restore':'remove'),[],$r['is_removed']?'Restore image':'Remove image');?></section><?php }});return;}
  throw new HttpError('Page not found.',404);
 }
 private static function content(array $u,string $method,string $path,array $d):void{if(preg_match('~^/community/manage/(news|rules)/(new|\d+)$~',$path,$m)){$kind=$m[1];$id=$m[2]==='new'?null:(int)$m[2];if($method==='POST'){$title=App::text($d['title']??null,'Title',180);$category=App::text($d['category']??null,'Category',80);$body=App::text($d['body']??null,'Content',$kind==='news'?50000:10000);$status=$d['status']??'';if(!in_array($status,['draft','published','archived'],true))throw new HttpError('Select a publication status.');App::transaction(function()use($u,$kind,$id,$d,$title,$category,$body,$status){if($id&&!App::row('SELECT id FROM community_'.$kind.' WHERE id=? FOR UPDATE',[$id]))throw new HttpError('Content not found.',404);if($kind==='news'){$tags=App::text($d['tags']??'','Tags',300,true);$summary=App::text($d['summary']??null,'Summary',500);if($id)App::query("UPDATE community_news SET title=?,category=?,tags=?,summary=?,body=?,status=?,published_at=IF(?='published',COALESCE(published_at,NOW()),published_at),updated_by=?,updated_at=NOW() WHERE id=?",[$title,$category,$tags?:null,$summary,$body,$status,$status,$u['id'],$id]);else $id=App::insert("INSERT INTO community_news(title,category,tags,summary,body,status,published_at,updated_by) VALUES(?,?,?,?,?,?,IF(?='published',NOW(),NULL),?)",[$title,$category,$tags?:null,$summary,$body,$status,$status,$u['id']]);}else{$order=filter_var($d['sort_order']??0,FILTER_VALIDATE_INT);if($order===false||$order<0||$order>100000)throw new HttpError('Order must be between 0 and 100000.');if($id)App::query('UPDATE community_rules SET title=?,category=?,body=?,status=?,sort_order=?,updated_by=?,updated_at=NOW() WHERE id=?',[$title,$category,$body,$status,$order,$u['id'],$id]);else $id=App::insert('INSERT INTO community_rules(title,category,body,status,sort_order,updated_by) VALUES(?,?,?,?,?,?)',[$title,$category,$body,$status,$order,$u['id']]);}App::audit((int)$u['id'],'community.content_saved','community_'.$kind,(int)$id,['status'=>$status]);});App::redirect('/community/manage');}$r=$id?($kind==='news'?Domain::post($id,true):App::row('SELECT * FROM community_rules WHERE id=?',[$id])):[];if($id&&!$r)throw new HttpError('Content not found.',404);View::layout('Content editor',function()use($r,$path,$kind){View::heading($kind==='news'?'News editor':'Rule editor');$fields=['title'=>['label'=>'Title','required'=>true],'category'=>['label'=>'Category','required'=>true],'body'=>['label'=>'Content','type'=>'textarea','required'=>true],'status'=>['label'=>'Status','options'=>['draft'=>'Draft','published'=>'Published','archived'=>'Archived']]];if($kind==='news')$fields+=['summary'=>['label'=>'Summary','type'=>'textarea','required'=>true],'tags'=>'Tags'];else $fields['sort_order']=['label'=>'Order','type'=>'number'];View::form($path,$fields,'Save content',$r);});return;}if($path!=='/community/manage')throw new HttpError('Page not found.',404);View::layout('News & rules',function(){View::heading('News & rules');?><div class="actions"><a class="btn" href="/community/manage/news/new">New update</a><a class="btn secondary" href="/community/manage/rules/new">New rule</a></div><?php foreach(['news'=>Domain::news([],true)['posts'],'rules'=>Domain::rules([],true)['rules']] as $kind=>$rows){?><section class="panel"><h2><?=escape(ucfirst($kind))?></h2><?php View::table($rows,['title'=>'Title','category'=>'Category','status'=>'Status'],function($r)use($kind){?><a href="/community/manage/<?=escape($kind)?>/<?=(int)$r['id']?>">Edit</a><?php });?></section><?php }});}
}
